for c in range(1, ws_d.max_column+1):
    v = ws_d.cell(header_row,c).value
    # Consider numeric years or strings that look like years; exclude code col and text labels
    if c != code_col and v is not None and re.fullmatch(r'\d{4}', str(v).strip()):
        header_cols.append(c)
if not header_cols:
    # fallback to non-empty headers to the right of code col
    header_cols = [c for c in range(code_col+1, ws_d.max_column+1) if ws_d.cell(header_row,c).value is not None]
first_data_col = min(header_cols)
last_data_col = max(header_cols)
first_data_col_letter = get_column_letter(first_data_col)
last_data_col_letter = get_column_letter(last_data_col)
print('\nFormula Data ranges selected:')
print(f'  Series codes: Data!${code_col_letter}$21:${code_col_letter}$38')
print(f'  Year headers: Data!${first_data_col_letter}${header_row}:${last_data_col_letter}${header_row}')
print(f'  Data body:    Data!${first_data_col_letter}$21:${last_data_col_letter}$38')

