print('\nData series code row mapping rows 21-38:')
for r in range(21,39):
    print(f'  {ws_d.cell(r, code_col).value!r} -> row {r}')

# Existing content/formatting in target ranges: use non-readonly workbook for styles
wb_style = load_workbook(src, read_only=False, data_only=False)
ws_ts = wb_style['Task']
target_ranges = ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
print('\nExisting content/formatting in target ranges (value presence, fill, number format, alignment):')
for rng in target_ranges:
