        vals.append(f'{get_column_letter(c)}{r}={v!r}')
        if not (isinstance(v,str) and v.startswith('=PERCENTILE(')):
            percentile_ok=False
        if isinstance(v,str) and ('PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v):
            percentile_ok=False
    print('  row', r, ':', ', '.join(vals))
print(f'  PERCENTILE (not dotted variants) OK = {percentile_ok}')

# Extra formula count/check
formula_targets=[]
for rng in target_ranges:
    for row in wsv[rng]:
        for cell in row:
            formula_targets.append(cell.value)
starts_equal = all(isinstance(v, str) and v.startswith('=') for v in formula_targets)
print(f'\nVerification summary: all targets formula strings={starts_equal}, all targets non-empty={all_nonempty}')
if not (starts_equal and all_nonempty and wbv.sheetnames == ['Task','Data'] and percentile_ok):
    raise SystemExit('Verification failed')
